-- Canonical map implementation
export func map[a, b](f: func(a) -> b, xs: [a]) -> [b] {
  match xs {
    [] => [],
    Cons(x, rest) => Cons(f(x), map(f, rest))
  }
}

-- Helper function to join a list of showable elements into a string
export func join[a](separator: string, xs: [a]) -> string {
  match xs {
    [] => "",
    Cons(x, []) => show(x), -- Last element, no separator after it
    Cons(x, rest) => show(x) ++ separator ++ join(separator, rest)
  }
}

export func main() -> () ! {IO} {
  let numbers = [1, 2, 3, 4, 5];
  let double = \x. x * 2;

  let doubledNumbers = map(double, numbers);
  let resultString = join(", ", doubledNumbers);

  println(resultString)
}

