type Result[a] = Ok(a) | Err(string)

export func parse_int(s: string) -> Result[int] {
  if s == "0" then Ok(0)
  else if s == "1" then Ok(1)
  else if s == "2" then Ok(2)
  else if s == "3" then Ok(3)
  else if s == "4" then Ok(4)
  else if s == "5" then Ok(5)
  else if s == "6" then Ok(6)
  else if s == "7" then Ok(7)
  else if s == "8" then Ok(8)
  else if s == "9" then Ok(9)
  else if s == "10" then Ok(10)
  else if s == "-1" then Ok(-1)
  else if s == "-2" then Ok(-2)
  else Err("Invalid integer")
}

export func divide_safe(a: int, b: int) -> Result[int] {
  if b == 0
  then Err("Division by zero")
  else Ok(a / b)
}

export func chain_operations(s: string, divisor: int) -> Result[int] {
  match parse_int(s) {
    Ok(value) => divide_safe(value, divisor),
    Err(msg) => Err(msg)
  }
}

export func format_result(result: Result[int]) -> string {
  match result {
    Ok(value) => "Result: " ++ show(value),
    Err(msg) => "Error: " ++ msg
  }
}

export func main() -> () ! {IO} {
  let r1 = chain_operations("10", 2);
  println(format_result(r1));

  let r2 = chain_operations("10", 0);
  println(format_result(r2));

  let r3 = chain_operations("abc", 2);
  println(format_result(r3))
}

