type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(Leaf(x), v, Leaf(y)) => {
      if v >= x && v >= y
      then v
      else if x >= y
      then x
      else y
    },
    Node(l, v, r) => {
      let lm = find_max(l);
      let rm = find_max(r);
      match v {
        n if n >= lm && n >= rm => n,
        _ => if lm >= rm then lm else rm
      }
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let sum = tree_sum(tree);
  let mx = find_max(tree);
  println("Sum: " ++ show(sum));
  println("Max: " ++ show(mx))
}

